<?php require_once __DIR__.'/config.php';$id=(int)($_GET['id']??0);$cat=null;foreach(data_load('categories.json') as $c)if((int)$c['id']===$id)$cat=$c;if(!$cat){http_response_code(404);exit('Раздел не найден');}$threads=array_reverse(array_filter(data_load('threads.json'),fn($t)=>(int)$t['category_id']===$id));?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($cat['title'])?> — GREFFRLEND</title><link rel="stylesheet" href="style.css"></head><body><header class="top"><div class="wrap nav"><a class="logo" href="index.php">GREFFRLEND</a><nav><a href="index.php">Главная</a><a href="rules.php">Правила</a></nav></div></header><main class="wrap"><h1><?=e($cat['title'])?></h1><p class="muted"><?=e($cat['description'])?></p><?php foreach($threads as $t):?><div class="card thread"><div><a href="thread.php?id=<?=$t['id']?>"><b><?=e($t['title'])?></b></a><div class="muted"><?=e($t['author'])?> · <?=e($t['created_at'])?></div></div><div class="stats"><?=count(data_load('replies_'.$t['id'].'.json'))?> ответов</div></div><?php endforeach;?><?php if(user()):?><a class="btn" href="create-thread.php?category=<?=$id?>">Создать тему</a><?php endif;?></main></body></html>